# Exercice 2 : a completer
def recherche_dichotomique(liste_triee, x):
    comparaisons = 0
    # TODO etudiant : implementer la recherche dichotomique en comptant les comparaisons
    return None


resultat = recherche_dichotomique(list(range(16)), 11)
if resultat is None:
    print("Exercice a completer : recherche_dichotomique renvoie encore None")
else:
    for k in (4, 8, 12, 16, 20):
        n = 2 ** k
        _, comparaisons = recherche_dichotomique(list(range(n)), -1)
        print(f"n = 2^{k:<2} : {comparaisons} comparaisons (recherche lineaire : {n})")

# Exercice 3 : a completer
transitions_parite = {}  # TODO etudiant : (etat, (symbole,)) -> (nouvel etat, ((ecriture, deplacement),))

if not transitions_parite:
    print("Exercice a completer : la table de transitions est vide")
else:
    parite = MachineTuring(1, transitions_parite, "pair", ["accepte"])
    for mot in ["0110", "1001", "000", "", "1", "0111"]:
        etat, _ = parite.run(mot)
        verdict = "accepte" if etat == "accepte" else "rejete"
        print(f"{mot!r:>8} : {verdict:<8} en {parite.pas} pas")

GRILLES = {
    "facile A": "902005403100063025508407060026309001057010290090670530240530600705200304080041950",
    "facile B": "000000907000420180000705026100904000050000040000507009920108000034059000507000000",
    "difficile A": "85...24..72......9..4.........1.7..23.5...9...4...........8..7..17..........36.4.",
    "difficile B": "12..4......5.69.1...9...5.........7.7...52.9..3......2.9.6...5.4..9..8.1..3...9.4",
}


def lire_grille(texte):
    return [0 if ch in ".0" else int(ch) for ch in texte]


def compatible(g, k, v):
    r, c = divmod(k, 9)
    for j in range(9):
        if g[r * 9 + j] == v or g[j * 9 + c] == v:
            return False
    br, bc = 3 * (r // 3), 3 * (c // 3)
    for i in range(3):
        for j in range(3):
            if g[(br + i) * 9 + bc + j] == v:
                return False
    return True


def trouver_backtracking(grille):
    # Remplit la grille en place ; retourne (reussite, nombre d'appels recursifs).
    appels = [0]

    def essayer():
        appels[0] += 1
        if 0 not in grille:
            return True
        k = grille.index(0)
        for v in range(1, 10):
            if compatible(grille, k, v):
                grille[k] = v
                if essayer():
                    return True
                grille[k] = 0
        return False

    return essayer(), appels[0]


def unites():
    lignes = [[r * 9 + c for c in range(9)] for r in range(9)]
    colonnes = [[r * 9 + c for r in range(9)] for c in range(9)]
    blocs = [[(3 * br + i) * 9 + 3 * bc + j for i in range(3) for j in range(3)]
             for br in range(3) for bc in range(3)]
    return lignes + colonnes + blocs


def verifier_grille(depart, proposee):
    # Certificat accepte ssi il respecte les indices de depart et chaque unite contient 1..9.
    lectures = 0
    for k in range(81):
        lectures += 1
        if depart[k] and proposee[k] != depart[k]:
            return False, lectures
    for unite in unites():
        vus = set()
        for k in unite:
            lectures += 1
            vus.add(proposee[k])
        if vus != set(range(1, 10)):
            return False, lectures
    return True, lectures


print(f"{'grille':>12} | {'appels (trouver)':>16} | {'lectures (verifier)':>19} | trouver / verifier")
print("-" * 74)
solutions = {}
for nom, texte in GRILLES.items():
    depart = lire_grille(texte)
    grille = list(depart)
    ok, appels = trouver_backtracking(grille)
    valide, lectures = verifier_grille(depart, grille)
    assert ok and valide, nom
    solutions[nom] = grille
    rapport = appels / lectures
    rapport_txt = f"{rapport:.2f}" if rapport < 10 else f"{rapport:,.0f}"
    print(f"{nom:>12} | {appels:>16,} | {lectures:>19} | {rapport_txt:>14}x".replace(",", " "))

# Un certificat faux doit etre refuse : echanger deux cases d'une solution
fausse = list(solutions["facile A"])
k1, k2 = next((a, b) for a in range(81) for b in range(a + 1, 81)
              if a // 9 == b // 9 and GRILLES["facile A"][a] == "0" and GRILLES["facile A"][b] == "0")
fausse[k1], fausse[k2] = fausse[k2], fausse[k1]
valide, lectures = verifier_grille(lire_grille(GRILLES["facile A"]), fausse)
print()
print(f"certificat falsifie (deux cases echangees) : accepte = {valide}, refuse apres {lectures} lectures")

def verifier_subset(poids, cible, indices):
    # Certificat = liste d'indices distincts ; retourne (accepte, operations).
    operations = 0
    if len(set(indices)) != len(indices):
        return False, operations
    somme = 0
    for i in indices:
        operations += 1
        if not 0 <= i < len(poids):
            return False, operations
        somme += poids[i]
    return somme == cible, operations


def subset_brut(poids, cible):
    # Force brute : enumere les 2^n sous-ensembles ; retourne (verdict, operations, certificat).
    n = len(poids)
    ops = 0
    for masque in range(2 ** n):
        s = 0
        for i in range(n):
            ops += 1
            if masque >> i & 1:
                s += poids[i]
        if s == cible:
            return True, ops, [i for i in range(n) if masque >> i & 1]
    return False, ops, None


def subset_dp(poids, cible):
    # Programmation dynamique : table booleenne sur les sommes 0..cible ; retourne (verdict, cases).
    atteignable = [False] * (cible + 1)
    atteignable[0] = True
    cases = 0
    for p in poids:
        for s in range(cible, p - 1, -1):
            cases += 1
            if atteignable[s - p]:
                atteignable[s] = True
    return atteignable[cible], cases


rng = np.random.default_rng(42)
print(f"{'n':>3} | {'ops brut':>10} | {'cases dp':>9} | {'ops verif':>9} | verdict")
print("-" * 52)
for n in (8, 11, 14, 17):
    poids = rng.integers(1, 60, size=n).tolist()
    cible = int(sum(poids) // 2)
    vb, ops_b, certificat = subset_brut(poids, cible)
    vd, cases_d = subset_dp(poids, cible)
    assert vb == vd, "les deux algorithmes doivent convenir"
    if vb:
        ok, ops_v = verifier_subset(poids, cible, certificat)
        assert ok, "le certificat trouve doit etre accepte"
    else:
        ops_v = "-"                 # reponse non : pas de certificat a verifier
    print(f"{n:>3} | {ops_b:>10} | {cases_d:>9} | {ops_v:>9} | {'oui' if vb else 'non'}")

class Ruban:
    """Ruban infini aux deux extremites, symbole blanc '_'."""
    def __init__(self, mot=""):
        self.cellules = {i: c for i, c in enumerate(mot)}
        self.tete = 0

    def lire(self):
        return self.cellules.get(self.tete, "_")

    def ecrire(self, c):
        self.cellules[self.tete] = c

    def deplacer(self, d):
        self.tete += 1 if d == "R" else (-1 if d == "L" else 0)


class MachineTuring:
    """Machine multitete au sens de Hartmanis-Stearns 1965, compteur de pas inclus.
    Retourne l'etat d'arret : un etat acceptant, ou None (blocage = rejet / budget epuise)."""
    def __init__(self, k_rubans, transitions, etat_initial, etats_acceptants):
        self.k = k_rubans
        self.delta = transitions  # (etat, symboles lus) -> (nouvel etat, [(ecriture, deplacement)] * k)
        self.q0 = etat_initial
        self.F = set(etats_acceptants)
        self.pas = 0

    def run(self, mot, max_pas=100_000):
        rubans = [Ruban(mot) if i == 0 else Ruban() for i in range(self.k)]
        etat = self.q0
        self.pas = 0
        while etat not in self.F:
            if self.pas >= max_pas:
                return None, rubans  # budget epuise
            lus = tuple(r.lire() for r in rubans)
            if (etat, lus) not in self.delta:
                return None, rubans  # blocage : rejet
            etat, ecritures = self.delta[(etat, lus)]
            for r, (c, d) in zip(rubans, ecritures):
                r.ecrire(c)
                r.deplacer(d)
            self.pas += 1
        return etat, rubans


def lire_ruban(r):
    if not r.cellules:
        return ""
    fin = max(r.cellules)
    return "".join(r.cellules.get(i, "_") for i in range(fin + 1)).rstrip("_")


# --- Machine A : increment binaire, 1 ruban ---
inc = MachineTuring(
    1,
    {
        ("q0", ("0",)): ("q0", (("0", "R"),)),
        ("q0", ("1",)): ("q0", (("1", "R"),)),
        ("q0", ("_",)): ("q1", (("_", "L"),)),
        ("q1", ("1",)): ("q1", (("0", "L"),)),
        ("q1", ("0",)): ("qF", (("1", "S"),)),
        ("q1", ("_",)): ("qF", (("1", "S"),)),
    },
    "q0", ["qF"],
)

etat, rubans = inc.run("1011")
print(f"increment('1011') -> {lire_ruban(rubans[0])} (attendu 1100), etat={etat}, {inc.pas} pas")

# --- 1a. Atteignabilite : le DFS deterministe (P) et sa pile ---
def dfs_atteignable(adj, s, t):
    vu = {s}
    pile = [s]
    pile_max = 1
    while pile:
        u = pile.pop()
        if u == t:
            return True, pile_max
        for v in adj[u]:
            if v not in vu:
                vu.add(v)
                pile.append(v)
                pile_max = max(pile_max, len(pile))
    return False, pile_max

def graphe_aleatoire(n, densite=1.5):
    adj = defaultdict(list)
    for u in range(n):
        for _ in range(int(densite)):
            v = GENERATEUR.randrange(n)
            adj[u].append(v)
    return adj

blocs_dfs = []
for n in (40, 100, 250, 600):
    adj = graphe_aleatoire(n, 4)
    (ok, pile_max), duree = chrono(dfs_atteignable, adj, 0, n - 1)
    blocs_dfs.append((n, ok, pile_max, duree))
    print(f"n={n:4d}  atteint={ok}  pile max (espace explore)={pile_max:4d}  temps={duree*1e3:8.3f} ms")

# --- 1c. P contre NP : 2-SAT lineaire, 3-SAT exponentiel, instances appariees ---
import sys

sys.setrecursionlimit(10000)  # Kosaraju recursif jusqu'a 2n = 1600 sommets (n = 800)

def deux_sat(clauses, nb_var):
    # Kosaraju (recursif, n petit) sur le graphe d'implications : temps lineaire, donc 2-SAT dans P.
    n = nb_var

    def lit(l):  # litteral signe -> index interne : x_i -> i-1, non-x_i -> i-1+n
        return abs(l) - 1 if l > 0 else abs(l) - 1 + n

    def neg(i):
        return i + n if i < n else i - n

    adj = [[] for _ in range(2 * n)]
    radj = [[] for _ in range(2 * n)]
    for (a, b) in clauses:
        la, lb = lit(a), lit(b)
        adj[neg(la)].append(lb)   # (a ou b) = (non-a -> b) et (non-b -> a)
        adj[neg(lb)].append(la)
        radj[lb].append(neg(la))
        radj[la].append(neg(lb))
    vu = [False] * (2 * n)
    ordre = []

    def dfs1(u):
        vu[u] = True
        for v in adj[u]:
            if not vu[v]:
                dfs1(v)
        ordre.append(u)

    for s in range(2 * n):
        if not vu[s]:
            dfs1(s)
    comp = [-1] * (2 * n)

    def dfs2(u, c):
        comp[u] = c
        for v in radj[u]:
            if comp[v] == -1:
                dfs2(v, c)

    c = 0
    for s in reversed(ordre):
        if comp[s] == -1:
            dfs2(s, c)
            c += 1
    if any(comp[i] == comp[i + n] for i in range(n)):
        return False, None
    val = {i: comp[i] > comp[i + n] for i in range(n)}
    return True, val

def trois_sat_dpll(clauses, nb_var):
    # DPLL (propagation de unite + branchement) avec compteur de noeuds explores :
    # metrique deterministe -- le temps varie d'une machine a l'autre, pas le nombre
    # de noeuds, propriete de l'instance ET de la strategie de branchement.
    noeuds = [0]

    def resoudre(partiel, restantes):
        noeuds[0] += 1
        while True:
            unitaires = [c[0] for c in restantes if len(c) == 1]
            if not unitaires:
                break
            l = unitaires[0]
            nouvelles = []
            for c in restantes:
                if l in c:
                    continue
                if -l in c:
                    c2 = [x for x in c if x != -l]
                    if not c2:
                        return None
                    nouvelles.append(c2)
                else:
                    nouvelles.append(c)
            restantes = nouvelles
            partiel = dict(partiel)
            partiel[abs(l)] = l > 0
        if not restantes:
            return partiel
        l = restantes[0][0]
        for choix in (l, -l):
            cand = [[x for x in c if x != -choix] for c in restantes if choix not in c]
            partiel2 = dict(partiel)
            partiel2[abs(choix)] = choix > 0
            resultat = resoudre(partiel2, cand)
            if resultat is not None:
                return resultat
        return None
    solution = resoudre({}, [list(c) for c in clauses])
    return solution is not None, solution, noeuds[0]

def verifier_3sat(clauses, solution):
    # L'arete P inclus dans NP : verifier un certificat est polynomial.
    return all(any((x > 0) == solution.get(abs(x), False) for x in c) for c in clauses)

def instance_2sat(n, m):
    clauses = []
    for _ in range(m):
        a = GENERATEUR.randrange(1, n + 1) * (1 if GENERATEUR.random() < 0.5 else -1)
        b = GENERATEUR.randrange(1, n + 1) * (1 if GENERATEUR.random() < 0.5 else -1)
        clauses.append((a, b))
    return clauses

def instance_3sat_plantee(n, m):
    # 3-CNF aleatoire (literal 50/50). Densite 4.6n : juste au-dessus du seuil de
    # satisfiabilite 4.267n, la ou les instances aleatoires sont les plus dures pour DPLL.
    clauses = []
    for _ in range(m):
        c = []
        while len(c) < 3:
            v = GENERATEUR.randrange(1, n + 1)
            if v not in [abs(x) for x in c]:
                c.append(v if GENERATEUR.random() < 0.5 else -v)
        clauses.append(c)
    return clauses

def instance_satisfiable(n, m, essais_max=12):
    for _ in range(essais_max):
        cl = instance_3sat_plantee(n, m)
        sat, _, _ = trois_sat_dpll(cl, n)
        if sat:
            return cl
    return cl

# 2-SAT : le probleme de P -- quatre fois plus de variables, ~quatre fois le temps
print("2-SAT (Kosaraju) -- moyenne sur 5 instances :")
for n in (50, 200, 800):
    cumul = 0.0
    for _ in range(5):
        clauses2 = instance_2sat(n, 3 * n)
        (sat2, _), d2 = chrono(deux_sat, clauses2, n)
        cumul += d2
    print(f"  n={n:4d}   {cumul / 5 * 1e3:8.3f} ms")

# 3-SAT : le probleme NP-complet -- meme question existentielle, densite au seuil
print("3-SAT (DPLL, densite 4.6n) -- moyenne sur 20 instances :")
tailles = (10, 15, 20, 25, 30)
noeuds_moyens = {}
temps_moyens = {}
for n in tailles:
    total_noeuds = 0
    cumul = 0.0
    for _ in range(20):
        clauses3 = instance_3sat_plantee(n, int(4.6 * n))
        (sat3, sol3, nds), d3 = chrono(trois_sat_dpll, clauses3, n)
        total_noeuds += nds
        cumul += d3
    noeuds_moyens[n] = total_noeuds / 20
    temps_moyens[n] = cumul / 20
    print(f"  n={n:3d}   noeuds DPLL : {noeuds_moyens[n]:8.1f}   {temps_moyens[n] * 1e3:8.3f} ms")

n0, n1 = tailles[0], tailles[-1]
facteur_noeuds = (noeuds_moyens[n1] / noeuds_moyens[n0]) ** (1.0 / (n1 - n0))
facteur_temps = (temps_moyens[n1] / temps_moyens[n0]) ** (1.0 / (n1 - n0))
print(f"Facteur de croissance par variable ajoutee (noeuds explores, deterministe) : ~{facteur_noeuds:.2f}x")
print(f"Facteur de croissance par variable ajoutee (temps) : ~{facteur_temps:.2f}x")

# L'arete P inclus dans NP, dans l'autre sens : le certificat se verifie en polynomial
certificats = 0
for _ in range(20):
    clauses3 = instance_satisfiable(12, 4 * 12)
    (sat3, sol3, _), _ = chrono(trois_sat_dpll, clauses3, 12)
    if sat3 and sol3 is not None and verifier_3sat(clauses3, sol3):
        certificats += 1
print(f"Certificats 3-SAT verifies en temps polynomial par verifier_3sat : {certificats} / 20")

# --- 2b. Monde B : oracle complet ou P^B = NP^B ---
def oracle_qbf(h, x):
    # L'oracle (stand-in PSPACE) evalue la formule quantifiee « existe y, h(x, y) »
    # par enumeration exhaustive. C'est SON travail : la machine ne paie rien.
    n = len(x)
    for entier_y in range(2 ** n):
        if h(x, format(entier_y, f"0{n}b")):
            return 1
    return 0

def machine_P_avec_oracle_qbf(x, h):
    # La machine P emet UNE requete et recopie la reponse : le langage existentiel
    # « existe y, h(x, y) » est lui-meme un QBF a un quantificateur -- une seule question a l'oracle.
    return oracle_qbf(h, x), 1

def machine_np_sans_oracle(x, h):
    # Le meme langage vu du cote NP SANS oracle : l'enumeration est payee par la machine.
    n = len(x)
    for entier_y in range(2 ** n):
        if h(x, format(entier_y, f"0{n}b")):
            return 1
    return 0

def h_jouet(x, y):
    return x.count("1") + y.count("1") >= len(x)

echantillon = [format(k, "05b") for k in (0, 5, 13, 21, 31)]
accord_b = True
for x in echantillon:
    rep_P, requetes = machine_P_avec_oracle_qbf(x, h_jouet)
    rep_NP = machine_np_sans_oracle(x, h_jouet)
    accord_b &= (rep_P == rep_NP)
    print(f"x={x}  P^B(x)={rep_P} ({requetes} requete)  NP^B(x)={rep_NP}  accord={rep_P == rep_NP}")
print("Monde B : la machine P a une requete egale la machine NP exhaustive :", accord_b)

# Pagination : k cases de mémoire, des pages demandées une par une.
def belady(requetes, k):
    """Optimum hors ligne (Belady 1966) : évincer la page dont le prochain usage est le plus lointain."""
    cache, defauts = set(), 0
    for t, r in enumerate(requetes):
        if r in cache:
            continue
        defauts += 1
        if len(cache) < k:
            cache.add(r)
            continue
        prochain = {p: float("inf") for p in cache}
        for u in range(t + 1, len(requetes)):
            if requetes[u] in cache and prochain[requetes[u]] == float("inf"):
                prochain[requetes[u]] = u
        cache.discard(max(prochain, key=lambda p: prochain[p]))
        cache.add(r)
    return defauts


def lru(requetes, k):
    """En ligne : évincer la page utilisée le plus anciennement."""
    cache, defauts = [], 0
    for r in requetes:
        if r in cache:
            cache.remove(r)
            cache.append(r)
            continue
        defauts += 1
        if len(cache) == k:
            cache.pop(0)
        cache.append(r)
    return defauts


def fifo(requetes, k):
    """En ligne, autre règle : évincer la page entrée le plus anciennement."""
    cache, defauts = [], 0
    for r in requetes:
        if r in cache:
            continue
        defauts += 1
        if len(cache) == k:
            cache.pop(0)
        cache.append(r)
    return defauts


print("Motif cyclique sur k+1 pages (l'adversaire choisit la suite)")
print(f"{'k':>2} | {'T':>4} | {'OPT':>5} | {'LRU':>4} | {'FIFO':>4} | {'rapport LRU':>11} | {'rapport FIFO':>12}")
ratio_lru_cyclique = {}
for k in (2, 3, 4, 5):
    for T in (60, 600):
        req = [i % (k + 1) for i in range(T)]
        o, l, f = belady(req, k), lru(req, k), fifo(req, k)
        ratio_lru_cyclique[(k, T)] = l / o
        print(f"{k:>2} | {T:>4} | {o:>5} | {l:>4} | {f:>4} | {l / o:>11.3f} | {f / o:>12.3f}")

req_alea = [int(x) for x in rng.integers(0, 20, size=600)]
print("\nMotif aleatoire (20 pages, 600 requetes, k = 5)")
o5, l5, f5 = belady(req_alea, 5), lru(req_alea, 5), fifo(req_alea, 5)
ratio_lru_aleatoire, ratio_fifo_aleatoire = l5 / o5, f5 / o5
